-- Retail chains --
CREATE TABLE "C##GIS_USER"."RETAIL_CHAINS"
  (
    "CHAIN_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1
    START WITH 1 CACHE 20 NOORDER NOCYCLE NOT NULL ENABLE,
    "CHAIN_NAME"        VARCHAR2(100 BYTE) NOT NULL ENABLE,
    "LEGAL_NAME"        VARCHAR2(255 BYTE),
    "HQ_COUNTRY_CODE"   CHAR(2 BYTE) NOT NULL ENABLE,
    "HQ_STATE_PROVINCE" VARCHAR2(50 BYTE),
    "HQ_CITY"           VARCHAR2(50 BYTE),
    "HQ_POSTAL_CODE"    VARCHAR2(20 BYTE),
    "HQ_HOUSE_NUMBER"   VARCHAR2(20 BYTE),
    "HQ_STREET"         VARCHAR2(100 BYTE),
    "RETAIL_TYPE"       VARCHAR2(20 BYTE),
    "BUSINESS_MODEL"    VARCHAR2(50 BYTE),
    "WEB_SITE"          VARCHAR2(4000 BYTE),
    "TICKER_SYMBOL"     VARCHAR2(10 BYTE),
    "STATUS"            VARCHAR2(20 BYTE),
    "CREATED_AT"        TIMESTAMP (6),
    "UPDATED_AT"        DATE,
    PRIMARY KEY ("CHAIN_ID") USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS TABLESPACE "USERS" ENABLE
  )
  SEGMENT CREATION DEFERRED PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 NOCOMPRESS LOGGING TABLESPACE "USERS" ;
COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."HQ_STATE_PROVINCE"
IS
  'Grocery, Apparel,...';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."HQ_CITY"
IS
  'Ciity where the headquarters is located';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."BUSINESS_MODEL"
IS
  'Corporate — company-owned stores, Franchise, Hybrid';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."WEB_SITE"
IS
  'WEB site URL';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."TICKER_SYMBOL"
IS
  'Stock ticker if the company is publicly traded (e.g., WMT for Walmart on the NYSE)';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."STATUS"
IS
  'Active, Inactive, Merged';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."CREATED_AT"
IS
  'Date and time of entry';
  COMMENT ON COLUMN "C##GIS_USER"."RETAIL_CHAINS"."UPDATED_AT"
IS
  'Date and time of last update';